// ============================================================
// Agent 16 — Vision Agent (ENHANCED)
// Phase: CREATE | Model: gemini-2.5-pro | Depends on: rewrite(15), headline-optimizer(14)
// ============================================================
// ENHANCEMENT: Receives story arc + 3 headline variants → generates
// 3 thumbnail concepts (one per headline), Creative Agent picks best.
// Also generates OG image concept, alt text, and featured image brief.
//
// LEARNING: Tracks which thumbnail concept styles drove highest CTR.
// ============================================================

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { geminiJson, GeminiError } from "../_shared/gemini.ts";
import { insertLog } from "../_shared/logger.ts";
import { writeAgentOutput, readAgentOutput, patchAgentState, loadRun } from "../_shared/pipeline.ts";

const AGENT_KEY = "vision";
const AGENT_NAME = "Vision";
const MODEL = "gemini-2.5-pro";

const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
const corsHeaders = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type" };

interface ThumbnailConcept {
  headline_variant: string;         // which headline this concept matches
  visual_style: string;             // "data-visualization" | "human-story" | "bold-text" | "abstract" | "product-photo"
  color_palette: string;            // specific colors (e.g., "Deep blue #1a237e + gold #f9a825")
  text_overlay: string;             // text to overlay on image (≤6 words)
  image_description: string;        // prompt for image generation (100 chars)
  composition: string;              // layout guidance
  emotional_register: string;       // the emotion this visual triggers
  ctr_prediction: number;           // 1-10 predicted thumbnail CTR
  platform_dimensions: {
    facebook: string; twitter: string; og: string; wordpress_featured: string;
  };
}

interface VisionOutput {
  thumbnail_concepts: ThumbnailConcept[];    // 3 concepts, one per headline variant
  recommended_concept_index: number;         // 0-based index of best concept
  featured_image_alt: string;               // SEO-friendly alt text
  og_image_brief: string;                   // OG image design brief (for Creative Agent)
  caption_suggestions: string[];            // 3 caption options for the image
  image_search_keywords: string[];          // for finding stock photos
  brand_color_consistent: boolean;          // does design follow LADtoday brand?
  learning_applied: boolean;
}

async function loadVisionLearning(category: string) {
  try {
    const { data } = await supabase.from("agent_memory").select("visual_style,actual_ctr_week1")
      .eq("agent_key", AGENT_KEY).in("topic_category", [category, "general"])
      .not("actual_ctr_week1", "is", null).order("actual_ctr_week1", { ascending: false }).limit(12);
    if (!data?.length) return { bestStyle: "bold-text", sampleSize: 0 };
    const counts: Record<string, number> = {};
    for (const m of data) if (m.visual_style) counts[m.visual_style] = (counts[m.visual_style] || 0) + 1;
    return { bestStyle: Object.entries(counts).sort(([,a],[,b])=>b-a)[0]?.[0] || "bold-text", sampleSize: data.length };
  } catch { return { bestStyle: "bold-text", sampleSize: 0 }; }
}

function inferCategory(t: string) {
  t = t.toLowerCase();
  if (/fintech|sbp|banking/.test(t)) return "fintech"; if (/tech|ai|startup/.test(t)) return "tech";
  if (/cricket|sport/.test(t)) return "sports"; if (/politics|government/.test(t)) return "politics";
  if (/economy|inflation/.test(t)) return "economy"; return "general";
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  const startedAt = Date.now();
  try {
    const h = req.headers.get("Authorization");
    if (!h?.startsWith("Bearer ")) return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });
    const t = h.replace("Bearer ", "");
    const isAuth = t === Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || (() => { try { return JSON.parse(atob(t.split(".")[1])).role === "service_role"; } catch { return false; } })();
    if (!isAuth) return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });

    const { run_id } = await req.json().catch(() => ({}));
    if (!run_id) return new Response(JSON.stringify({ error: "run_id required" }), { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } });

    const run = await loadRun(run_id);
    const topic = run.topic || "";
    const category = inferCategory(topic);

    await insertLog("ai", AGENT_KEY, `${AGENT_NAME} started`, topic, { run_id });
    await patchAgentState(run_id, AGENT_KEY, { status: "running", started_at: new Date().toISOString() });

    const [rewriteOut, headlineOut, storyOut] = await Promise.all([
      readAgentOutput(run_id, "rewrite"),
      readAgentOutput(run_id, "headline-optimizer").catch(() => null),
      readAgentOutput(run_id, "story-arc").catch(() => null),
    ]);
    if (!rewriteOut) throw new Error("rewrite output not found");

    const learning = await loadVisionLearning(category);

    // Get 3 headline variants for thumbnail concepts
    const h1 = headlineOut?.top_headline?.headline || topic;
    const h2 = headlineOut?.social_headline?.headline || topic;
    const h3 = headlineOut?.platform_best?.twitter?.headline || topic;
    const hook = storyOut?.hook_text || "";
    const structure = storyOut?.structure_type || "analysis";
    const excerpt = rewriteOut.article_text?.slice(0, 400) || "";

    const prompt = `You are the Vision Agent for LADtoday — Pakistan's AI content platform.
Generate 3 thumbnail concepts (one per headline) that will drive clicks.

TOPIC: "${topic}" | CATEGORY: ${category}
STRUCTURE TYPE: ${structure}
ARTICLE EXCERPT: "${excerpt.slice(0,300)}"
${learning.sampleSize > 0 ? `LEARNING: "${learning.bestStyle}" visual style drove highest CTR in ${learning.sampleSize} past runs — bias toward it.` : ""}

HEADLINE VARIANTS:
1. "${h1}" (primary/SEO)
2. "${h2}" (social/emotional)
3. "${h3}" (Twitter/bold)

For each headline, design a matching thumbnail concept. The visual must COMPLEMENT the headline tone.

VISUAL STYLES:
- data-visualization: charts, percentages, infographic style — for data-heavy articles
- human-story: faces, personal narrative — for human interest
- bold-text: large typography + simple background — for opinion/claim headlines
- abstract: geometric/conceptual — for trend/analysis
- product-photo: real objects/UI screenshots — for tech/product articles

PLATFORM DIMENSIONS:
- facebook: 1200x630px
- twitter: 1200x675px
- og: 1200x630px
- wordpress_featured: 1920x1080px

Return JSON:
{
  "thumbnail_concepts": [
    {
      "headline_variant": "string (the headline this matches)",
      "visual_style": "data-visualization|human-story|bold-text|abstract|product-photo",
      "color_palette": "string (e.g. 'Deep navy #1a237e + gold accent #f9a825 + white text')",
      "text_overlay": "string (≤6 words for image overlay, impactful)",
      "image_description": "string (100-char image generation prompt)",
      "composition": "string (layout guidance: 'left-aligned text, right side: chart graphic')",
      "emotional_register": "string (emotion this visual triggers)",
      "ctr_prediction": number (1-10),
      "platform_dimensions": {"facebook":"1200x630","twitter":"1200x675","og":"1200x630","wordpress_featured":"1920x1080"}
    }
  ],
  "recommended_concept_index": number (0-2, index of best concept),
  "featured_image_alt": "string (SEO alt text, describe image + keyword, ≤125 chars)",
  "og_image_brief": "string (detailed brief for Creative Agent to design OG image)",
  "caption_suggestions": ["string (3 image caption options)"],
  "image_search_keywords": ["string (5 keywords for stock photo search)"]
}`;

    const schema = { type: "object", properties: {
      thumbnail_concepts: { type: "array", items: { type: "object", properties: {
        headline_variant:{type:"string"}, visual_style:{type:"string"}, color_palette:{type:"string"},
        text_overlay:{type:"string"}, image_description:{type:"string"}, composition:{type:"string"},
        emotional_register:{type:"string"}, ctr_prediction:{type:"number"},
        platform_dimensions:{type:"object",properties:{facebook:{type:"string"},twitter:{type:"string"},og:{type:"string"},wordpress_featured:{type:"string"}}},
      }}},
      recommended_concept_index:{type:"integer"}, featured_image_alt:{type:"string"},
      og_image_brief:{type:"string"}, caption_suggestions:{type:"array",items:{type:"string"}},
      image_search_keywords:{type:"array",items:{type:"string"}},
    }};

    const raw = await geminiJson<any>(prompt, schema, { model: MODEL, temperature: 0.65, maxOutputTokens: 2500 });
    const result: VisionOutput = {
      thumbnail_concepts: raw.thumbnail_concepts || [],
      recommended_concept_index: raw.recommended_concept_index || 0,
      featured_image_alt: raw.featured_image_alt || topic.slice(0, 125),
      og_image_brief: raw.og_image_brief || "",
      caption_suggestions: raw.caption_suggestions || [],
      image_search_keywords: raw.image_search_keywords || [],
      brand_color_consistent: true,
      learning_applied: learning.sampleSize > 0,
    };

    const topConcept = result.thumbnail_concepts[result.recommended_concept_index];
    try {
      await supabase.from("agent_memory").insert({ agent_key: AGENT_KEY, topic_category: category, visual_style: topConcept?.visual_style || "bold-text", actual_ctr_week1: null, created_at: new Date().toISOString() });
    } catch {/**/ }

    const durationMs = Date.now() - startedAt;
    await writeAgentOutput(run_id, AGENT_KEY, result, { tokens: Math.ceil(JSON.stringify(result).length / 4), duration_ms: durationMs, status: "completed" });
    await patchAgentState(run_id, AGENT_KEY, { status: "completed", finished_at: new Date().toISOString(), concepts: result.thumbnail_concepts.length, recommended: result.recommended_concept_index });
    await insertLog("ai", AGENT_KEY, `${AGENT_NAME} completed`, `${result.thumbnail_concepts.length} thumbnail concepts | recommended=[${result.recommended_concept_index}] style=${topConcept?.visual_style} | ${durationMs}ms`, { run_id });

    return new Response(JSON.stringify({ ok: true, agent: AGENT_KEY, run_id, concepts: result.thumbnail_concepts.length, recommended_style: topConcept?.visual_style, duration_ms: durationMs }), { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[${AGENT_NAME}] ❌`, msg);
    try { const b = await req.clone().json().catch(()=>({})); if (b.run_id) { await patchAgentState(b.run_id, AGENT_KEY, { status: "failed", error: msg, finished_at: new Date().toISOString() }); await writeAgentOutput(b.run_id, AGENT_KEY, { error: msg }, { status: "failed", error: msg, duration_ms: Date.now() - startedAt }); } } catch {/**/ }
    await insertLog("error", AGENT_KEY, `${AGENT_NAME} failed`, msg);
    return new Response(JSON.stringify({ error: msg }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
});

// Shared Gemini helper used by all backend AI functions.
// Reads GEMINI_API_KEY from server secrets and calls Google's Generative Language API.
// Never expose this key to the frontend.

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY") || "";

// Centralized model id so we can change it in one place later.
export const GEMINI_TEXT_MODEL = "gemini-2.5-flash";

export class GeminiError extends Error {
  status: number;
  code: string;
  constructor(message: string, status: number, code: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

function ensureKey() {
  if (!GEMINI_API_KEY) {
    throw new GeminiError(
      "Gemini API key missing. Add GEMINI_API_KEY as a backend secret.",
      500,
      "missing_key"
    );
  }
}

function normalizeError(status: number, body: string): GeminiError {
  // Try to surface a clear, actionable message
  let detail = body;
  try {
    const parsed = JSON.parse(body);
    detail = parsed?.error?.message || body;
  } catch { /* ignore */ }

  if (status === 400 && /API key/i.test(detail)) {
    return new GeminiError(`Gemini rejected the API key: ${detail}`, 401, "invalid_key");
  }
  if (status === 401 || status === 403) {
    return new GeminiError(`Gemini authentication failed: ${detail}`, 401, "invalid_key");
  }
  if (status === 429) {
    return new GeminiError(
      `Gemini quota exceeded. Check Google AI Studio billing/quota for this API key. Detail: ${detail}`,
      429,
      "quota_exceeded"
    );
  }
  return new GeminiError(`Gemini API error ${status}: ${detail}`, 500, "api_error");
}

interface GeminiContent {
  parts: { text: string }[];
}

/**
 * Call Gemini for a plain text completion.
 * Returns the generated text (trimmed).
 */
export async function geminiText(
  prompt: string,
  opts?: { model?: string; maxOutputTokens?: number; temperature?: number }
): Promise<string> {
  ensureKey();
  const model = opts?.model || GEMINI_TEXT_MODEL;
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`;

  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: opts?.temperature ?? 0.8,
        maxOutputTokens: opts?.maxOutputTokens ?? 1024,
      },
    }),
  });

  if (!res.ok) throw normalizeError(res.status, await res.text());
  const data = await res.json();
  const candidate = data?.candidates?.[0];
  const parts: GeminiContent["parts"] | undefined = candidate?.content?.parts;
  const text = (parts || []).map((p) => p.text || "").join("").trim();
  if (!text) {
    throw new GeminiError("Empty response from Gemini.", 500, "empty_response");
  }
  return text;
}

/**
 * Call Gemini and force a structured JSON response that matches the given schema.
 * Returns the parsed object.
 *
 * `schema` follows the Gemini responseSchema format (a JSON Schema subset).
 */
export async function geminiJson<T = any>(
  prompt: string,
  schema: Record<string, any>,
  opts?: { model?: string; maxOutputTokens?: number; temperature?: number }
): Promise<T> {
  ensureKey();
  const model = opts?.model || GEMINI_TEXT_MODEL;
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`;

  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: opts?.temperature ?? 0.7,
        maxOutputTokens: opts?.maxOutputTokens ?? 8192,
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    }),
  });

  if (!res.ok) throw normalizeError(res.status, await res.text());
  const data = await res.json();
  const text = (data?.candidates?.[0]?.content?.parts || [])
    .map((p: any) => p.text || "")
    .join("")
    .trim();

  if (!text) throw new GeminiError("Empty JSON response from Gemini.", 500, "empty_response");

  try {
    return JSON.parse(text) as T;
  } catch {
    // Try to recover by extracting the first {...} or [...] block
    const match = text.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
    if (match) {
      try { return JSON.parse(match[0]) as T; } catch { /* fallthrough */ }
    }
    throw new GeminiError(`Gemini returned malformed JSON: ${text.slice(0, 300)}`, 500, "bad_json");
  }
}

export function hasGeminiKey(): boolean {
  return !!GEMINI_API_KEY;
}

// Lobster Trap — lightweight guard layer wrapping Gemini calls.
// Runs cheap heuristic checks (injection, PII), logs to lobstertrap_audit.
// Drop-in replacements for geminiText / geminiJson that ALSO take run/agent context.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  GeminiError,
  GEMINI_TEXT_MODEL,
  geminiJson,
  geminiText,
} from "./gemini.ts";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
);

export interface GuardContext {
  runId?: string | null;
  agentKey: string;
  model?: string;
}

const INJECTION_PATTERNS: RegExp[] = [
  /ignore (all |the )?(previous|prior|above) instructions/i,
  /disregard (all |the )?(previous|prior|above)/i,
  /you are now (a |an )?[a-z ]+ (assistant|ai|bot)/i,
  /system prompt[:\s]/i,
  /<\/?\|im_(start|end)\|>/i,
  /\bjailbreak\b/i,
  /reveal (your|the) (system )?prompt/i,
];

const PII_CHECKS: { type: string; re: RegExp }[] = [
  { type: "email", re: /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i },
  { type: "phone", re: /(\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3,4}[ -]?\d{4}/ },
  { type: "cnic", re: /\b\d{5}-\d{7}-\d\b/ },                 // Pakistani CNIC
  { type: "credit_card", re: /\b(?:\d[ -]*?){13,16}\b/ },
];

export function scanPrompt(prompt: string) {
  const sample = prompt.slice(0, 8000);
  const injection_detected = INJECTION_PATTERNS.some((re) => re.test(sample));
  const pii_types: string[] = [];
  for (const { type, re } of PII_CHECKS) if (re.test(sample)) pii_types.push(type);
  const pii_detected = pii_types.length > 0;

  let risk = 0;
  if (injection_detected) risk += 0.6;
  if (pii_detected) risk += 0.3;
  risk = Math.min(1, risk);
  return { injection_detected, pii_detected, pii_types, risk_score: risk };
}

async function logAudit(row: Record<string, any>) {
  try {
    await supabase.from("lobstertrap_audit").insert(row);
  } catch (e) {
    console.error("lobstertrap audit insert failed", e);
  }
}

async function decideAction(scan: ReturnType<typeof scanPrompt>) {
  // Read policy from settings (best-effort; default deny on injection).
  let denyInjection = true;
  let quarantinePii = false;
  try {
    const { data } = await supabase
      .from("settings")
      .select("value")
      .eq("key", "guardian_policy")
      .maybeSingle();
    const policy = data?.value as any;
    if (policy?.deny_injection === false) denyInjection = false;
    if (policy?.quarantine_pii === true) quarantinePii = true;
  } catch { /* ignore */ }

  if (scan.injection_detected && denyInjection) return "DENY";
  if (scan.pii_detected && quarantinePii) return "QUARANTINE";
  if (scan.risk_score > 0.3) return "LOG";
  return "ALLOW";
}

export async function guardedGeminiText(
  prompt: string,
  ctx: GuardContext,
  opts?: Parameters<typeof geminiText>[1]
): Promise<string> {
  const startedAt = Date.now();
  const scan = scanPrompt(prompt);
  const action = await decideAction(scan);
  const model = opts?.model || ctx.model || GEMINI_TEXT_MODEL;

  if (action === "DENY") {
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: 0,
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "BLOCKED",
      latency_ms: Date.now() - startedAt,
      error: "Blocked by Lobster Trap (injection)",
    });
    throw new GeminiError("Blocked by Lobster Trap (injection detected)", 451, "blocked");
  }

  try {
    const text = await geminiText(prompt, opts);
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: Math.ceil(text.length / 4),
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "APPROVED",
      latency_ms: Date.now() - startedAt,
    });
    return text;
  } catch (e) {
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: 0,
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "REVIEW",
      latency_ms: Date.now() - startedAt,
      error: e instanceof Error ? e.message : String(e),
    });
    throw e;
  }
}

export async function guardedGeminiJson<T = any>(
  prompt: string,
  schema: Record<string, any>,
  ctx: GuardContext,
  opts?: Parameters<typeof geminiJson>[2]
): Promise<T> {
  const startedAt = Date.now();
  const scan = scanPrompt(prompt);
  const action = await decideAction(scan);
  const model = opts?.model || ctx.model || GEMINI_TEXT_MODEL;

  if (action === "DENY") {
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: 0,
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "BLOCKED",
      latency_ms: Date.now() - startedAt,
      error: "Blocked by Lobster Trap (injection)",
    });
    throw new GeminiError("Blocked by Lobster Trap (injection detected)", 451, "blocked");
  }

  try {
    const out = await geminiJson<T>(prompt, schema, opts);
    const responseSize = JSON.stringify(out).length;
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: Math.ceil(responseSize / 4),
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "APPROVED",
      latency_ms: Date.now() - startedAt,
    });
    return out;
  } catch (e) {
    await logAudit({
      run_id: ctx.runId ?? null,
      agent_key: ctx.agentKey,
      model,
      prompt_preview: prompt.slice(0, 240),
      prompt_tokens: Math.ceil(prompt.length / 4),
      response_tokens: 0,
      injection_detected: scan.injection_detected,
      pii_detected: scan.pii_detected,
      pii_types: scan.pii_types,
      risk_score: scan.risk_score,
      action_taken: action,
      verdict: "REVIEW",
      latency_ms: Date.now() - startedAt,
      error: e instanceof Error ? e.message : String(e),
    });
    throw e;
  }
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
);

export async function insertLog(
  level: "info" | "warning" | "error" | "ai" | "system",
  source: string,
  message: string,
  details?: string,
  metadata?: Record<string, any>
): Promise<void> {
  try {
    await supabase.from("admin_logs").insert({
      level,
      source,
      message,
      details: details || null,
      metadata: metadata || {},
    });
  } catch (e) {
    console.error("Failed to insert log:", e);
  }
}

// Pipeline orchestration helpers shared across agent edge functions.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
);

export { supabase };

export interface AgentRow {
  key: string;
  name: string;
  phase: string;
  order_index: number;
  depends_on: string[];
  model: string;
  enabled: boolean;
}

export interface RunRow {
  id: string;
  topic: string;
  input_type: string;
  input_payload: any;
  brand_voice: string;
  language: string;
  status: string;
  enabled_agents: string[] | null;
  agent_states: Record<string, any>;
}

export async function loadRegistry(): Promise<AgentRow[]> {
  const { data, error } = await supabase
    .from("agent_registry")
    .select("*")
    .order("order_index");
  if (error) throw new Error(`loadRegistry: ${error.message}`);
  return (data || []) as AgentRow[];
}

export async function loadRun(runId: string): Promise<RunRow> {
  const { data, error } = await supabase
    .from("pipeline_runs")
    .select("*")
    .eq("id", runId)
    .single();
  if (error) throw new Error(`loadRun: ${error.message}`);
  return data as RunRow;
}

export async function updateRun(runId: string, patch: Record<string, any>) {
  const { error } = await supabase
    .from("pipeline_runs")
    .update(patch)
    .eq("id", runId);
  if (error) throw new Error(`updateRun: ${error.message}`);
}

export async function patchAgentState(
  runId: string,
  agentKey: string,
  patch: Record<string, any>
) {
  // Optimistic merge by re-reading agent_states.
  const { data, error } = await supabase
    .from("pipeline_runs")
    .select("agent_states")
    .eq("id", runId)
    .single();
  if (error) throw new Error(`patchAgentState read: ${error.message}`);
  const states = (data?.agent_states as Record<string, any>) || {};
  states[agentKey] = { ...(states[agentKey] || {}), ...patch };
  const { error: upErr } = await supabase
    .from("pipeline_runs")
    .update({ agent_states: states })
    .eq("id", runId);
  if (upErr) throw new Error(`patchAgentState write: ${upErr.message}`);
}

/**
 * Write agent output to agent_outputs table.
 * Overloaded to accept (runId, agentKey, output, meta?) directly.
 */
export async function writeAgentOutput(
  runId: string,
  agentKey: string,
  output: any,
  meta?: { tokens?: number; duration_ms?: number; status?: string; error?: string }
) {
  const { error } = await supabase
    .from("agent_outputs")
    .upsert({
      run_id: runId,
      agent_key: agentKey,
      output,
      status: meta?.status || "completed",
      tokens: meta?.tokens || 0,
      duration_ms: meta?.duration_ms || null,
      error: meta?.error || null,
    }, { onConflict: "run_id,agent_key" });
  if (error) throw new Error(`writeAgentOutput: ${error.message}`);
}

/**
 * Read agent output from agent_outputs table.
 */
export async function readAgentOutput(runId: string, agentKey: string): Promise<any> {
  const { data, error } = await supabase
    .from("agent_outputs")
    .select("output, status")
    .eq("run_id", runId)
    .eq("agent_key", agentKey)
    .maybeSingle();
  if (error) throw new Error(`readAgentOutput: ${error.message}`);
  return data?.output || null;
}

/**
 * Decide which agents are ready to run given current state.
 * An agent is runnable when:
 *  - it is enabled in the registry (and in run.enabled_agents if set)
 *  - it has no state yet (status missing or "pending")
 *  - all its deps have agent_states[dep].status === "completed"
 *    (deps that are disabled are considered satisfied — skipped)
 */
export function nextRunnableAgents(run: RunRow, registry: AgentRow[]): AgentRow[] {
  const states = run.agent_states || {};
  const allowSet = run.enabled_agents
    ? new Set(run.enabled_agents)
    : null;
  const enabledMap = new Map<string, boolean>();
  for (const a of registry) {
    const enabled = a.enabled && (allowSet ? allowSet.has(a.key) : true);
    enabledMap.set(a.key, enabled);
  }

  const ready: AgentRow[] = [];
  for (const a of registry) {
    if (!enabledMap.get(a.key)) continue;
    const st = states[a.key]?.status;
    if (st === "running" || st === "completed" || st === "failed") continue;
    const depsOk = a.depends_on.every((dep) => {
      if (!enabledMap.get(dep)) return true; // disabled deps don't block
      return states[dep]?.status === "completed";
    });
    if (depsOk) ready.push(a);
  }
  return ready;
}

export function isTerminal(run: RunRow, registry: AgentRow[]): { done: boolean; failed: boolean } {
  const states = run.agent_states || {};
  const allowSet = run.enabled_agents ? new Set(run.enabled_agents) : null;
  let anyFailed = false;
  let allDone = true;
  for (const a of registry) {
    const enabled = a.enabled && (allowSet ? allowSet.has(a.key) : true);
    if (!enabled) continue;
    const st = states[a.key]?.status;
    if (st === "failed") anyFailed = true;
    if (st !== "completed" && st !== "failed") allDone = false;
  }
  return { done: allDone, failed: anyFailed };
}

/// Map DAG keys to actual edge function directory names (simplified folder names).
const SHORT_TO_FN: Record<string, string> = {
